mapper.select:
SELECT segment_index, seat_type, price
FROM train_segment_price
WHERE train_id = #{trainId}
  AND seat_type = #{seatType}
  AND segment_index BETWEEN #{fromSegmentIndex}
                        AND #{toSegmentIndex}
ORDER BY segment_index

mapper.update:
UPDATE ticket_stock
SET sold_count      = sold_count + #{count},
    remaining_count = remaining_count - #{count},
    version         = version + 1
WHERE travel_date = #{travelDate}
  AND train_id = #{trainId}
  AND seat_type = #{seatType}
  AND segment_index BETWEEN #{fromSegmentIndex}
                        AND #{toSegmentIndex}
  AND remaining_count >= #{count}

mapper.select:
SELECT COUNT(*)
FROM ticket_order o
WHERE o.user_id = #{userId}

  AND o.status = #{status}

SELECT 
FROM ticket_order o
LEFT JOIN station station_from
       ON station_from.id = o.from_station_id
LEFT JOIN station station_to
       ON station_to.id = o.to_station_id
WHERE o.user_id = #{userId}

  AND o.status = #{status}

ORDER BY o.created_at DESC, o.id DESC
LIMIT #{size} OFFSET #{offset}

mapper.update:
UPDATE ticket_order
SET status = 1,
    paid_at = #{paidAt}
WHERE id = #{id}
  AND status = 0

UPDATE ticket_order
SET status = 2,
    cancelled_at = #{cancelledAt}
WHERE id = #{id}
  AND status = 0

UPDATE ticket_stock
SET sold_count      = sold_count - #{count},
    remaining_count = remaining_count + #{count},
    version         = version + 1
WHERE travel_date = #{travelDate}
  AND train_id = #{trainId}
  AND seat_type = #{seatType}
  AND segment_index BETWEEN #{fromSegmentIndex}
                        AND #{toSegmentIndex}
  AND sold_count >= #{count}
  AND remaining_count + #{count} <= total_count

